import{_ as t,r as l,o as d,c,e as i,a as r,b as o,d as s,w as n}from"./chunks/framework.DRBGAJkr.js";const p="/assets/pila_osi.CRDiXjzf.png",u="/assets/1_tcp_ip.7JNLt9mc.jpg",m="/assets/capas_tcp_ip.aYBerTjN.png",g="/assets/Internet_osi.CvopI3PU.png",v="/assets/1_comunicacion.V2OqMqvQ.png",f="/assets/2_comunicacion.B3ZJdH6e.png",S=JSON.parse('{"title":"Modelo OSI","description":"","frontmatter":{"title":"Modelo OSI"},"headers":[],"relativePath":"02_Web_old/02_redes/01_osi/index.md","filePath":"02_Web_old/02_redes/01_osi/index.md"}'),P={name:"02_Web_old/02_redes/01_osi/index.md"};function b(q,e,_,I,T,C){const a=l("Color");return d(),c("div",null,[e[17]||(e[17]=i('<div class="daws-objetivos"><div class="daws-objetivos__header"><i class="fa-solid fa-list-check" aria-hidden="true"></i><span>Objetivos</span></div><div class="daws-objetivos__content"><div class="daws-objetivos__title">Qué veremos aquí</div><div class="daws-objetivos__body"><ul><li>Modelo OSI</li><li>Modelo TCP/IP</li><li>Concepto de protocolo</li><li>Proceso de comunicación extremo a extremo</li></ul></div></div></div><h2 id="introduccion-al-modelo-osi" tabindex="-1">Introducción al Modelo OSI <a class="header-anchor" href="#introduccion-al-modelo-osi" aria-label="Permalink to &quot;Introducción al Modelo OSI&quot;">​</a></h2>',2)),r("p",null,[e[2]||(e[2]=o("El ",-1)),s(a,null,{default:n(()=>[...e[0]||(e[0]=[o("modelo OSI",-1)])]),_:1}),e[3]||(e[3]=o(" (Open Systems Interconnection) es un marco conceptual (es la base para la construcción y definición de redes), que define ",-1)),s(a,null,{default:n(()=>[...e[1]||(e[1]=[o("cómo las aplicaciones en una red pueden comunicarse entre sí.",-1)])]),_:1})]),r("p",null,[e[5]||(e[5]=o("Fue desarrollado por la ",-1)),s(a,null,{default:n(()=>[...e[4]||(e[4]=[o("ISO (Organización Internacional de Normalización)",-1)])]),_:1}),e[6]||(e[6]=o(" en 1984 para estandarizar las funciones de comunicación de los sistemas de red.",-1))]),r("p",null,[e[8]||(e[8]=o("El modelo OSI se divide en ",-1)),s(a,null,{default:n(()=>[...e[7]||(e[7]=[o("siete capas",-1)])]),_:1}),e[9]||(e[9]=o(", cada una de las cuales describe una parte específica del proceso de comunicación.",-1))]),r("p",null,[e[12]||(e[12]=o("Estas capas van desde el ",-1)),s(a,null,{default:n(()=>[...e[10]||(e[10]=[o("nivel físico",-1)])]),_:1}),e[13]||(e[13]=o(", donde se produce la transferencia física de bits a través de señales eléctricas o inalámbricas, hasta las ",-1)),s(a,null,{default:n(()=>[...e[11]||(e[11]=[o("aplicaciones de usuario",-1)])]),_:1}),e[14]||(e[14]=o(", facilitando la comunicación entre distintos sistemas y aplicaciones de red.",-1))]),e[18]||(e[18]=i('<p>Las siete capas son:</p><ol><li><strong>Capa Física</strong></li><li><strong>Capa de Enlace de Datos</strong></li><li><strong>Capa de Red</strong></li><li><strong>Capa de Transporte</strong></li><li><strong>Capa de Sesión</strong></li><li><strong>Capa de Presentación</strong></li><li><strong>Capa de Aplicación</strong></li></ol><p>El modelo OSI es fundamental para entender cómo las redes organizan y gestionan las comunicaciones entre dispositivos.</p><p><img src="'+p+'" alt="Pila OSI"></p><p>La idea es que cada capa de diferentes dispositivos se comuniquen de forma directa a través de lo que es el protocolo.</p><p>El modelo OSI es una especificación formal y en él se basan la construcción de redes reales como conjunto de protocolos que permiten la comunicación.</p><p>Una red real, que todos conocemos, es la red TCP/IP o red de internet.</p><p><img src="'+u+'" alt="Modelo TCP/IP"></p><p><a href="https://www.lawebdelprogramador.com/pdf/15788-Modelo-OSI-y-dispositivos-de-red-por-capa.html" target="_blank" rel="noreferrer">Modelo OSI y dispositivos de red por capa</a></p><hr><p>La siguiente imagen muestra la responsabilidad de capas agrupadas, que constituirán una sola capa en el modelo real de la red de internet o TCP/IP.</p><p><img src="'+m+'" alt="Capas TCP/IP"></p><p><a href="https://domoticaparatodos.com/2016/11/capas-en-los-protocolos/" target="_blank" rel="noreferrer">Capas en los protocolos</a></p><p>De forma ilustrativa, la siguiente imagen muestra la relación de capa/s OSI con las capas de la red de tipo TCP/IP.</p><p><img src="'+g+'" alt="Internet y OSI"></p><h3 id="protocolos" tabindex="-1">Protocolos <a class="header-anchor" href="#protocolos" aria-label="Permalink to &quot;Protocolos&quot;">​</a></h3><h4 id="¿que-es-un-protocolo" tabindex="-1">¿Qué es un protocolo? <a class="header-anchor" href="#¿que-es-un-protocolo" aria-label="Permalink to &quot;¿Qué es un protocolo?&quot;">​</a></h4><p>Un <strong>protocolo</strong> es un conjunto de <strong>reglas</strong> que permite que dos dispositivos diferentes puedan intercambiar <strong>datos</strong>, no información, de manera que ambos dispositivos se <strong>entiendan</strong>. Estas reglas aseguran que la comunicación entre los dispositivos sea <strong>lógica</strong> y de <strong>extremo a extremo</strong>, es decir, desde el origen hasta el destino sin perder coherencia en el proceso.</p><h4 id="protocolo-como-software" tabindex="-1">Protocolo como software <a class="header-anchor" href="#protocolo-como-software" aria-label="Permalink to &quot;Protocolo como software&quot;">​</a></h4><p>Un protocolo no es un concepto abstracto, se materializa en un <strong>software</strong> o <strong>programa</strong> que implementa estas reglas, permitiendo que la comunicación se lleve a cabo.</p><p>Los <strong>protocolos de nivel superior</strong> (como los de la capa de aplicación) se materializan en programas que el usuario o el administrador pueden instalar y configurar como un <strong>servicio</strong> o <strong>servidor</strong> en un equipo, que generalmente se denomina <strong>servidor</strong> y suele ser más potente que un equipo normal.</p><h4 id="protocolos-y-el-sistema-operativo" tabindex="-1">Protocolos y el sistema operativo <a class="header-anchor" href="#protocolos-y-el-sistema-operativo" aria-label="Permalink to &quot;Protocolos y el sistema operativo&quot;">​</a></h4><p>Los <strong>protocolos de nivel inferior</strong> (capa de sesión, red, enlace-físico) forman parte del <strong>sistema operativo</strong> y se instalan automáticamente con él. Esto sucedió por primera vez en una distribución de <strong>Unix</strong> desarrollada por la Universidad de <strong>Berkeley</strong>, que integró de manera nativa estos protocolos en el sistema.</p>',23)),s(a,null,{default:n(()=>[...e[15]||(e[15]=[o("El Unix de Berkeley (BSD)",-1)])]),_:1}),e[19]||(e[19]=o(" integró ",-1)),s(a,null,{default:n(()=>[...e[16]||(e[16]=[o("los protocolos TCP/IP de forma nativa en 1983",-1)])]),_:1}),e[20]||(e[20]=i(', lo que contribuyó de manera significativa a la expansión de las redes de computadoras y, eventualmente, de Internet.<hr><p>La siguiente imagen muestra las capas de nivel de una red de internet de tipo TCP/IP.</p><p><img src="'+v+'" alt="Comunicación TCP/IP"></p><h2 id="proceso-de-comunicacion" tabindex="-1">Proceso de comunicación <a class="header-anchor" href="#proceso-de-comunicacion" aria-label="Permalink to &quot;Proceso de comunicación&quot;">​</a></h2><p>Analiza la siguiente imagen para concretar cómo se produce una comunicación lógica de información a nivel de capas y la comunicación física o intercambio de datos a nivel lógico.</p><p><img src="'+f+'" alt="Proceso de comunicación"></p><h2 id="proceso-de-comunicacion-en-redes" tabindex="-1">Proceso de comunicación en redes <a class="header-anchor" href="#proceso-de-comunicacion-en-redes" aria-label="Permalink to &quot;Proceso de comunicación en redes&quot;">​</a></h2><p>Para que se produzca una <strong>comunicación lógica de extremo a extremo</strong> en los diferentes niveles o capas, cada <strong>protocolo</strong> incluye (cuando se encapsula en el emisor) o extrae y analiza (cuando desencapsula en recepción o destino), añadiendo a los datos una <strong>cabecera</strong> o información correspondiente al nivel en el que se encuentra.</p><h3 id="proceso-de-comunicacion-1" tabindex="-1">Proceso de comunicación <a class="header-anchor" href="#proceso-de-comunicacion-1" aria-label="Permalink to &quot;Proceso de comunicación&quot;">​</a></h3><p>El proceso de encapsulación y desencapsulación sigue una serie de pasos que involucran diferentes capas del modelo OSI y TCP/IP.</p><h4 id="en-el-emisor" tabindex="-1">En el emisor <a class="header-anchor" href="#en-el-emisor" aria-label="Permalink to &quot;En el emisor&quot;">​</a></h4><ol><li><p><strong>Nivel de Aplicación</strong>: En la capa de aplicación, los datos que el usuario quiere enviar se procesan según el protocolo de la aplicación (HTTP, FTP, SMTP, etc.). Aquí, se trocea la información (habitualmente llamada <strong>datos o mensaje</strong>), que se pasa al nivel de transporte.</p></li><li><p><strong>Nivel de Transporte</strong>: En esta capa, el protocolo de transporte (TCP o UDP) añade una <strong>cabecera</strong> a cada trozo de datos, que se denomina <strong>segmento</strong> (en el caso de TCP) o <strong>datagrama</strong> (en el caso de UDP). Esta cabecera incluye, entre otras cosas, el <strong>número de puerto</strong>, que es un identificador único que permite saber qué aplicación en el dispositivo de destino debe recibir los datos.</p><ul><li><strong>TCP</strong> es un protocolo orientado a la conexión que asegura la entrega fiable de los datos.</li><li><strong>UDP</strong> es un protocolo no orientado a la conexión, que ofrece una entrega más rápida pero sin garantías de fiabilidad.</li></ul></li><li><p><strong>Nivel de Red</strong>: El nivel de red utiliza el protocolo <strong>IP</strong> para realizar el enrutamiento de los datos. En este nivel, los <strong>segmentos</strong> de la capa de transporte se encapsulan en <strong>paquetes IP</strong>. La cabecera de IP contiene información clave, como la <strong>dirección IP de origen y destino</strong>, lo que permite a los routers dirigir el paquete al dispositivo correcto.</p><p>Es importante destacar que para <strong>IP</strong>, todo lo que recibe de la capa de transporte, incluidos los datos y las cabeceras de TCP o UDP, es tratado como una unidad de datos. Cada nivel del modelo nunca accede al contenido interno de los datos, solo manipula y analiza su propia cabecera.</p></li><li><p><strong>Nivel de Enlace</strong>: En el nivel de enlace, los <strong>paquetes</strong> de IP se encapsulan en <strong>tramas</strong>. La cabecera de una trama contiene información como las <strong>direcciones MAC</strong> (que identifican de forma única a los dispositivos dentro de la red local). Además, la trama incluye mecanismos de control de errores, como bits de redundancia para detectar y corregir errores. Un protocolo como <strong>Hamming</strong> puede ser utilizado para este propósito, permitiendo detectar y corregir un porcentaje de errores en la transmisión.</p></li><li><p><strong>Nivel Físico</strong>: Finalmente, la capa física se encarga de transmitir las <strong>señales eléctricas</strong>, <strong>ondas electromagnéticas</strong> (en redes inalámbricas), <strong>señales luminosas</strong> (si usamos medios de fibra óptica) o de otra naturaleza, en función del medio que usemos para la transmisión. Estas señales representan los bits que viajan a través del medio de transmisión (como cables de cobre, fibra óptica, o aire en redes inalámbricas). En este nivel, se lleva a cabo la <strong>conversión de los datos</strong> en señales físicas que pueden viajar por el medio de comunicación.</p></li></ol><h4 id="proceso-inverso-receptor" tabindex="-1">Proceso inverso (receptor) <a class="header-anchor" href="#proceso-inverso-receptor" aria-label="Permalink to &quot;Proceso inverso (receptor)&quot;">​</a></h4><p>En el receptor, ocurre el <strong>proceso inverso</strong>, conocido como <strong>desencapsulación</strong>. Los datos recibidos en la capa física son convertidos de señales a bits, que pasan a la capa de enlace, donde se analizan las tramas y se verifica la integridad de los datos. Después, el paquete IP es enviado a la capa de red, donde se lee la cabecera IP y se entrega el segmento al nivel de transporte, que finalmente entrega los datos a la aplicación correspondiente según el número de puerto.</p><h3 id="terminos-clave" tabindex="-1">Términos clave <a class="header-anchor" href="#terminos-clave" aria-label="Permalink to &quot;Términos clave&quot;">​</a></h3><ul><li><strong>Segmento</strong>: unidad de datos en el nivel de transporte (TCP).</li><li><strong>Datagrama</strong>: unidad de datos en el nivel de transporte (UDP).</li><li><strong>Paquete</strong>: unidad de datos en el nivel de red (IP).</li><li><strong>Trama</strong>: unidad de datos en el nivel de enlace.</li><li><strong>Señal</strong>: representación física de los datos en el nivel físico.</li></ul>',17))])}const h=t(P,[["render",b]]);export{S as __pageData,h as default};
